#include <iostream>
#include <string>
#include <sstream>
using namespace std;

struct Semver { int major, minor, patch; };

Semver parse(const string& s) {
    Semver v;
    sscanf(s.c_str(), "%d.%d.%d", &v.major, &v.minor, &v.patch);
    return v;
}

int compare(Semver a, Semver b) {
    if (a.major != b.major) return a.major < b.major ? -1 : 1;
    if (a.minor != b.minor) return a.minor < b.minor ? -1 : 1;
    if (a.patch != b.patch) return a.patch < b.patch ? -1 : 1;
    return 0;
}

int main() {
    Semver a = parse("1.2.3");
    Semver b = parse("1.10.0");
    cout << "A: " << a.major << "." << a.minor << "." << a.patch << endl;
    cout << "B: " << b.major << "." << b.minor << "." << b.patch << endl;
    cout << "Compare: " << compare(a, b) << endl;
    return 0;
}
